import sys
from collections import defaultdict

def is_palindrome(s, k):
    for i in range(k // 2):
        if s[i] != s[k - i - 1]:
            return False
    return True

def count_valid_permutations(n, k, s):
    if k == n:
        return 1 if not is_palindrome(s, k) else 0

    dp = [defaultdict(int) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for mask in range(1 << 26):
            for j in range(26):
                if mask & (1 << j):
                    new_mask = mask ^ (1 << j)
                    if is_palindrome(s[i - 1], k):
                        dp[i][new_mask] += dp[i - 1][mask]
                    else:
                        dp[i][new_mask] += dp[i - 1][mask] * (n - i + 1)

    return sum(dp[n][mask] for mask in range(1 << 26))

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    k = int(data[1])
    s = data[2]
    print(count_valid_permutations(n, k, s))
