import sys

def main():
    H, W, Q = map(int, sys.stdin.readline().split())
    grid = [[1] * W for _ in range(H)]
    wall_positions = set()

    for _ in range(Q):
        R_q, C_q = map(int, sys.stdin.readline().split())
        R_q -= 1
        C_q -= 1

        if grid[R_q][C_q] == 0:
            # No wall at (R_q, C_q), destroy the first walls in each direction
            for i in range(R_q - 1, -1, -1):
                if grid[i][C_q] == 1:
                    grid[i][C_q] = 0
                    wall_positions.remove((i, C_q))
                    break
            for i in range(R_q + 1, H):
                if grid[i][C_q] == 1:
                    grid[i][C_q] = 0
                    wall_positions.remove((i, C_q))
                    break
            for j in range(C_q - 1, -1, -1):
                if grid[R_q][j] == 1:
                    grid[R_q][j] = 0
                    wall_positions.remove((R_q, j))
