def main():
    # Read input
    N, M = map(int, sys.stdin.readline().split())
    pieces = set()
    non_capturable = set()

    # Read existing pieces
    for _ in range(M):
        a, b = map(int, sys.stdin.readline().split())
        pieces.add((a - 1, b - 1))

    # Check each square
    for i in range(N):
        for j in range(N):
            if (i, j) not in pieces:
                # Check if the square can be captured
                if any((i, k) in pieces for k in range(N)):
                    continue
                if any((k, j) in pieces for k in range(N)):
                    continue
                if any((i + j, k) in pieces for k in range(N)):
                    continue
                if any((i - j, k) in pieces for k in range(N)):
                    continue
                # If not captured, add to non-capturable set
                non_capturable.add((i, j))

    # Output the number of non-capturable squares
    print(len(non_capturable))

if __name__ == "__main__":
