def solve():
    A, B, M = map(int, sys.stdin.readline().split())

    # Initialize DP table
    dp = [[0] * (B + 1) for _ in range(A + 1)]
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, A + 1):
        for j in range(B + 1):
            if i > 0:
                dp[i][j] += dp[i - 1][j]
            if j > 0:
                dp[i][j] += dp[i][j - 1]

    # Calculate the number of valid permutations
    result = 0
    for i in range(A + 1):
        for j in range(B + 1):
            if i + j == A + B - 1:
                result += dp[i][j]

    # Print the result modulo M
    print(result % M)

