class TrieNode:
    def __init__(self):
        self.children = [None] * 2
        self.max_xor = 0

def insert(node, num, depth):
    if depth == 0:
        return
    bit = (num >> (depth - 1)) & 1
    if node.children[bit] is None:
        node.children[bit] = TrieNode()
    node.children[bit].max_xor = max(node.children[bit].max_xor, num)
    insert(node.children[bit], num, depth - 1)

def query(node, num, depth):
    if depth == 0:
        return 0
    bit = (num >> (depth - 1)) & 1
    if bit == 0:
        if node.children[1] is not None:
            return node.children[1].max_xor ^ num
        else:
            return node.children[0].max_xor ^ num
    else:
        if node.children[0] is not None:
            return node.children[0].max_xor ^ num
        else:
            return node.children[1].max_xor ^ num

def max_xor_subset(A, K):
    if K == 1:
        return max(A)

    root = TrieNode()
