def count_snake_numbers(L, R):
    def is_snake_number(num_str):
        num = int(num_str)
        if num < L or num > R:
            return False
        top_digit = int(num_str[0])
        for digit in num_str[1:]:
            if int(digit) >= top_digit:
                return False
        return True

    def generate_snake_numbers(current_num, pos, max_digit):
        if pos == len(current_num):
            return 1 if is_snake_number(current_num) else 0
        count = 0
