        if r is None:
            r = self.n - 1
        if l > r:
            return
        if l == r:
            self.tree[node] += val
            return
        mid = (l + r) // 2
        self.update(idx, val, l, mid, 2 * node + 1)
        self.update(idx, val, mid + 1, r, 2 * node + 2)
