import sys
from typing import List

def min_operations_to_sort(P: List[int]) -> int:
    N = len(P)
    operations = 0
    sorted_set = set()

    for i in range(N):
        if P[i] != i + 1:
            # Find the smallest k such that P[i-k+1] to P[i] is sorted
            for k in range(1, N - i + 1):
                if all(P[j] <= P[j + 1] for j in range(i - k + 1, i)):
                    operations += 1
                    sorted_set.update(range(i - k + 1, i + 1))
                    break

    return operations

def main():
    T = int(input())
    for _ in range(T):
        N = int(input())
        P = list(map(int, input().split()))
        print(min_operations_to_sort(P))

if __name__ == "__main__":
    main()
```

This Python code implements the solution to the problem by iterating through each element of the permutation and determining the minimum number of operations required to sort the subarray containing that element. The operations are counted and printed for each test case.

