    MOD = 998244353

    # Function to check if a string is a valid parenthesis sequence
    def is_valid(seq):
        stack = []
        for char in seq:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack[-1] != '(':
                    return False
                stack.pop()
        return len(stack) == 0

